# Real-World: Type-Safe User Model 👤

```typescript
type UserId = string | number;

function createAccount(id: UserId, email: string, isVerified: boolean = false): [UserId, string, boolean] {
  return [id, email.toLowerCase().trim(), isVerified];
}

const newAccount = createAccount("USR-891", "  ALICE@EXAMPLE.COM ", true);
console.log("Created Account Tuple:", newAccount);
```

